files.content:
* {
  box-sizing: border-box;
}

body {
  font-family: 'Open Sans', sans-serif;
  background-color: #5f0dee;
}

.parent {
  max-width: 100%;
  min-height: 100vh;
  padding: 60px 40px;
}

.login__link {
  display: flex;
  align-items: center;
  gap: 10px;
  width: min(100%, 320px);
  margin: auto;
  border: 1px solid #000;
  padding: 15px 30px;
  font-family: inherit;
  font-weight: 800;
  font-size: 24px;
  line-height: 1;
  text-decoration: none;
  text-transform: uppercase;
  background-color: #ffc802;
  cursor: pointer;
}

.login__icon {
  width: 3em;
}

.description {
  width: 100%;
  background: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.description-p {
  width: max(66%, 280px);
  /* Код здесь */
  margin: 0 0 0 auto;
  padding: 12px 25px;
  color: #fff;
  background-color: #5f0dee;
}

.main-content {
  display: flex;
  justify-content: center;
  margin: 40px 0;
} 

.grid-wrapper {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  margin: 40px auto;
  padding: 0;
  list-style: none;
}

.grid-item {
  border: 1px solid black;
  padding: 25px;
  font-style: italic;
  word-break: break-word;
  background-color: #fff;
}

.main-block {
  width: max(50%, 450px);
  border: 1px solid black;
  padding: 25px;
  background-color: #fff;
}

.aside-block {
  width: min(50%, 450px);
  border: 1px solid black;
  border-right: none;
  background-image: url(./images/img.jpg);
  background-position: center;
  background-size: cover;
}

.title {
  font-weight: 800;
  text-transform: uppercase;
}
